package _959.server_waypoint.common.client.integrations;

import com.mamiyaotaru.voxelmap.util.Waypoint;
import net.minecraft.world.item.ItemStack;
import org.jetbrains.annotations.Nullable;

import java.util.Collections;
import java.util.Map;
import java.util.WeakHashMap;

/**
 * Item icons carried by synced VoxelMap waypoints. VoxelMap only stores an image suffix, so an item
 * icon cannot travel through {@link Waypoint#imageSuffix} and is kept beside the waypoint instead.
 * Keys are weak so removed waypoints drop their icon without an explicit cleanup pass.
 */
public final class VoxelMapItemIcons {
    private static final Map<Waypoint, ItemStack> ICONS = Collections.synchronizedMap(new WeakHashMap<>());

    private VoxelMapItemIcons() {
    }

    public static void put(Waypoint waypoint, ItemStack icon) {
        ICONS.put(waypoint, icon);
    }

    public static @Nullable ItemStack get(Waypoint waypoint) {
        return ICONS.get(waypoint);
    }

    public static void remove(Waypoint waypoint) {
        ICONS.remove(waypoint);
    }

    public static void clear() {
        ICONS.clear();
    }
}
