package _959.server_waypoint.common.client.integrations;

/**
 * Where VoxelMap draws a minimap marker relative to the minimap centre, mirroring the geometry in
 * {@code Map#drawWaypoint} so synced item icons sit exactly where VoxelMap's own markers would.
 */
public final class VoxelMapMarkerOffset {
    /** Rotation of the marker around the minimap centre, and its distance from that centre. */
    public record Offset(float angleDegrees, double distance) {
    }

    private VoxelMapMarkerOffset() {
    }

    public static Offset of(double baseX, double baseZ, int waypointX, int waypointZ,
                            boolean rotates, float direction, int northRotate,
                            double zoomScaleAdjusted, boolean squareMap) {
        double wayX = baseX - waypointX - 0.5;
        double wayZ = baseZ - waypointZ - 0.5;
        float locate = (float) Math.toDegrees(Math.atan2(wayX, wayZ));
        double distance = Math.sqrt(wayX * wayX + wayZ * wayZ);
        if (rotates) {
            locate += direction;
        } else {
            locate -= northRotate;
        }
        distance /= zoomScaleAdjusted;
        if (squareMap) {
            double radLocate = Math.toRadians(locate);
            double dispX = distance * Math.cos(radLocate);
            double dispZ = distance * Math.sin(radLocate);
            if (Math.abs(dispX) > 28.5 || Math.abs(dispZ) > 28.5) {
                distance = distance / Math.max(Math.abs(dispX), Math.abs(dispZ)) * 30.0;
            }
        } else if (distance >= 31.0) {
            // Off-map waypoints hug the circular minimap edge.
            distance = 34.0;
        }
        return new Offset(locate, distance);
    }
}
