    /**
     * Resolves the item icon a synced VoxelMap marker should draw in place of VoxelMap's own image.
     * VoxelMap reloads its waypoints from file, so the marker is resolved from its synced name rather
     * than from the instance this mod created.
     */
    public static @Nullable ItemStack resolveItemIcon(Waypoint waypoint, WaypointFilesManagerCore waypointFiles) {
        SyncedEditTarget target = resolveSyncedEditTarget(waypoint, waypointFiles);
