        NamespacedId iconId = target.waypoint().icon();
        if (iconId == null || iconId.namespace().equals("voxelmap")) {
            return null;
        }
        WaypointIconRenderer.ResolvedIcon icon = WaypointIconRenderer.resolve(iconId);
        return icon.kind() == WaypointIconRenderer.Kind.ITEM ? icon.item() : null;
    }
